WITH powrprof_access_times AS (
  SELECT DISTINCT time
  FROM audit_logs
  WHERE object LIKE '%powrprof.dll%'
    AND access IS NOT NULL
),
processes_around_powrprof AS (
  SELECT time, pname, pid, ppid, command_line
  FROM audit_logs
  WHERE time IN (
    SELECT time FROM powrprof_access_times
  )
  OR time BETWEEN (
    SELECT MIN(time) FROM powrprof_access_times
  ) AND (
    SELECT MAX(time) FROM powrprof_access_times
  )
)
SELECT time, pname, pid, ppid, command_line
FROM audit_logs
WHERE time BETWEEN (
  (SELECT MIN(time) FROM powrprof_access_times) - INTERVAL 10 MINUTE
) AND (
  (SELECT MAX(time) FROM powrprof_access_times) + INTERVAL 10 MINUTE
)
ORDER BY time;

